INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Jedi advancement: from student to mentor','jedi-advanced-ranks','Proposed stages: Student, Foundation Graduate, Practitioner, Steward and Mentor. Foundation graduation requires the existing examination. Practitioner requires a sustained reflective practice and a documented learning project. Steward requires voluntary service and demonstrated accountability. Mentor requires supervised teaching and independent review. Titles are community recognitions, not proof of supernatural ability or administrative authority. Members may remain at any stage indefinitely.',0 FROM categories c CROSS JOIN users u WHERE c.slug='jedi-temple' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Sith advancement: the path of self-mastery','sith-advanced-ranks','Proposed stages: Student, Foundation Graduate, Adept, Ascendant and Mentor. Adept requires a documented personal discipline project. Ascendant requires evidence of constructive achievement, ethical judgment and reflection on setbacks. Mentor requires supervised teaching and independent review. Advancement never requires submission to another member, humiliation, violence or financial tribute.',0 FROM categories c CROSS JOIN users u WHERE c.slug='order-of-the-sith' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Jedi initiation: the commitment to learning','jedi-initiation-rite','A voluntary ceremony may begin with a moment of silence, followed by a reflection on a mistake that taught the participant something. The participant chooses a commitment to learning, compassion and responsible action. A witness acknowledges the commitment without claiming authority over the participant. No public confession, payment or disclosure of private experiences is required. A solitary ceremony is equally valid.',0 FROM categories c CROSS JOIN users u WHERE c.slug='jedi-temple' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Sith initiation: the declaration of sovereignty','sith-initiation-rite','A voluntary ceremony begins by naming a limitation the participant wishes to overcome, privately if preferred. The participant chooses a constructive goal and a measurable first action. A witness may acknowledge the declaration without demanding allegiance. Symbolic darkness represents unexplored possibilities, not permission to harm. No dangerous ordeal or compulsory disclosure is required.',0 FROM categories c CROSS JOIN users u WHERE c.slug='order-of-the-sith' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Mentorship covenant and boundaries','force-mentorship-covenant','Mentorship is an educational relationship entered and ended by mutual consent. Agree on learning goals, meeting frequency and boundaries. Mentors must not demand money, secrecy, romantic access or obedience as a condition of advancement. Private journals remain private. A learner may request a different mentor or independent review. Evaluate the relationship periodically against its stated goals.',0 FROM categories c CROSS JOIN users u WHERE c.slug='force-studies' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'A proposed annual cycle of Force observances','force-annual-cycle','January: renewal and goal setting. March: reflection on change. June: service or constructive achievement. September: study and dialogue. November: remembrance and gratitude. December: review and recommitment. These are optional Knightfall observances, not ancient traditions or astronomical requirements. Each order may develop its own ceremonies while retaining a shared day of respectful dialogue.',0 FROM categories c CROSS JOIN users u WHERE c.slug='force-studies' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Canon chronology: the Republic to the sequel era','history-canon-chronology','Begin with the High Republic publishing era, followed by the late Republic and the prequel trilogy. The Clone Wars culminate in the fall of the Republic and the rise of the Empire. The original trilogy depicts the rebellion and the defeat of the Emperor at Endor. The Mandalorian explores the post-Endor period; the sequel trilogy follows the conflict with the First Order. This is a broad reading sequence, not an exhaustive dated chronology.',0 FROM categories c CROSS JOIN users u WHERE c.slug='galactic-history' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Legends chronology: ancient orders to the New Jedi Order','history-legends-chronology','Legends includes ancient Jedi and Sith conflicts, Tales of the Jedi, the Knights of the Old Republic era, the later Sith wars and Darth Bane''s restructuring of the Sith. The familiar film-era conflicts lead into a separate post-Endor literary continuity, including the New Jedi Order and later Legacy stories. These developments should not be assumed to occur in current Canon.',0 FROM categories c CROSS JOIN users u WHERE c.slug='galactic-history' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Character dossier: Qui-Gon Jinn','character-qui-gon','Canon starting points: The Phantom Menace and The Clone Wars season six. Qui-Gon is a Jedi Master whose independent judgment and attention to the Living Force distinguish his approach. His disagreement with the Council over Anakin illustrates the tension between institutional caution and personal conviction. Discussion: when does principled dissent become overconfidence?',0 FROM categories c CROSS JOIN users u WHERE c.slug='holocron-archives' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Character dossier: Darth Bane','character-darth-bane','Canon recognizes Darth Bane as the Sith associated with the Rule of Two; his appearance in The Clone Wars is a starting point. The Legends Darth Bane novels provide a much fuller, continuity-specific account. His restructuring of the Sith is a fictional case study in organizational survival and concentrated power, not a prescription for real religious leadership.',0 FROM categories c CROSS JOIN users u WHERE c.slug='holocron-archives' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Ancient Force traditions: the Nightsisters','force-nightsisters','The Nightsisters of Dathomir practice a distinctive form of magick in The Clone Wars and later Canon stories. Their tradition illustrates that Force-related beliefs extend beyond Jedi and Sith institutions. Legends contains different and expanded accounts of Dathomiri traditions. Compare the portrayals without assuming that fictional rituals have demonstrated real-world supernatural effects.',0 FROM categories c CROSS JOIN users u WHERE c.slug='force-studies' AND u.username='knightfall' AND u.role='god';
INSERT OR IGNORE INTO threads(category_id,user_id,title,slug,body,pinned) SELECT c.id,u.id,'Sith lineages: Bane, Sidious and the Rule of Two','history-sith-lineages','The Rule of Two associates Sith continuity with a master and apprentice. Canon identifies Bane with the rule and depicts Sidious training multiple apprentices across his career. Legends supplies additional named lineages and histories that should be catalogued separately. The fictional system creates a tension between continuity and rivalry; living communities can study that tension without adopting betrayal as a virtue.',0 FROM categories c CROSS JOIN users u WHERE c.slug='galactic-history' AND u.username='knightfall' AND u.role='god';